-- Outfit armour: catalog rows for the 97 wearable items (outfits.js + cape)
-- and one worn item per equipment slot. Generated by scripts/build-outfit-catalog.mjs.
--
-- * item:armor:<key>  shop/inventory row; "slot" is the machine slot (helm, chest, ...).
-- * armor:<key>       combat row summed for defence and damage absorption.
--   Bank-note rows are created by the existing catalog trigger.
-- * equip: armour must be equipped into its catalog slot (legacy keys fall back to
--   slot = key, as before), and wearing an item takes off other armour in that slot.
--   Applied as a guarded edit: aborts unless the function is exactly the reviewed version.
begin;

with spec as (select r->>0 k,r->>1 name,(r->>2)::int buy,(r->>3)::int sell,r->>4 slot,(r->>5)::int defence,(r->>6)::int reduction,r->>7 outfit,r->>8 descr from jsonb_array_elements('[["helm","Iron armet helm",60,18,"helm",4,1,"knight"],["knightArmet2","Gilded armet helm",132,40,"helm",9,2,"knight"],["knightArmet3","Blacksteel armet helm",96,29,"helm",6,2,"knight"],["knightHornedHelm1","Iron horned helm",80,24,"helm",5,1,"knight"],["knightHornedHelm2","Gilded horned helm",176,53,"helm",11,2,"knight"],["knightHornedHelm3","Blacksteel horned helm",128,38,"helm",8,2,"knight"],["chest","Iron breastplate",60,18,"chest",10,3,"knight"],["knightBreastplate2","Gilded breastplate",132,40,"chest",22,7,"knight"],["knightBreastplate3","Blacksteel breastplate",96,29,"chest",16,5,"knight"],["knightGambeson1","Iron gambeson",30,9,"chest",4,1,"knight"],["knightGambeson2","Gilded gambeson",66,20,"chest",9,2,"knight"],["knightGambeson3","Blacksteel gambeson",48,14,"chest",6,2,"knight"],["knightGauntlets1","Iron gauntlets",40,12,"arms",3,1,"knight"],["knightGauntlets2","Gilded gauntlets",88,26,"arms",7,2,"knight"],["knightGauntlets3","Blacksteel gauntlets",64,19,"arms",5,2,"knight"],["legs","Iron greaves",60,18,"legs",7,2,"knight"],["knightGreaves2","Gilded greaves",132,40,"legs",15,4,"knight"],["knightGreaves3","Blacksteel greaves",96,29,"legs",11,3,"knight"],["boots","Iron sabatons",60,18,"boots",3,1,"knight"],["knightSabatons2","Gilded sabatons",132,40,"boots",7,2,"knight"],["knightSabatons3","Blacksteel sabatons",96,29,"boots",5,2,"knight"],["knightRoundPauldrons1","Iron round pauldrons",40,12,"shoulders",2,1,"knight"],["knightRoundPauldrons2","Gilded round pauldrons",88,26,"shoulders",4,2,"knight"],["knightRoundPauldrons3","Blacksteel round pauldrons",64,19,"shoulders",3,2,"knight"],["knightSpikedPauldrons1","Iron spiked pauldrons",55,17,"shoulders",3,1,"knight"],["knightSpikedPauldrons2","Gilded spiked pauldrons",121,36,"shoulders",7,2,"knight"],["knightSpikedPauldrons3","Blacksteel spiked pauldrons",88,26,"shoulders",5,2,"knight"],["knightScarf1","Iron scarf",15,5,"neck",0,0,"knight"],["knightScarf2","Gilded scarf",33,10,"neck",0,0,"knight"],["knightScarf3","Blacksteel scarf",24,7,"neck",0,0,"knight"],["nobleCrown1","Crimson crown",250,75,"helm",1,0,"noble"],["nobleCrown2","Royal blue crown",250,75,"helm",1,0,"noble"],["nobleCrown3","Emerald crown",250,75,"helm",1,0,"noble"],["nobleGorget1","Crimson gorget",60,18,"neck",2,1,"noble"],["nobleGorget2","Royal blue gorget",60,18,"neck",2,1,"noble"],["nobleGorget3","Emerald gorget",60,18,"neck",2,1,"noble"],["noblePauldron1","Crimson pauldron",60,18,"shoulders",2,1,"noble"],["noblePauldron2","Royal blue pauldron",60,18,"shoulders",2,1,"noble"],["noblePauldron3","Emerald pauldron",60,18,"shoulders",2,1,"noble"],["nobleLionPauldron1","Crimson lion pauldron",120,36,"shoulders",3,1,"noble"],["nobleLionPauldron2","Royal blue lion pauldron",120,36,"shoulders",3,1,"noble"],["nobleLionPauldron3","Emerald lion pauldron",120,36,"shoulders",3,1,"noble"],["nobleCoat1","Crimson noble coat",90,27,"chest",3,1,"noble"],["nobleCoat2","Royal blue noble coat",90,27,"chest",3,1,"noble"],["nobleCoat3","Emerald noble coat",90,27,"chest",3,1,"noble"],["nobleSleeves1","Crimson noble sleeves",45,14,"arms",1,0,"noble"],["nobleSleeves2","Royal blue noble sleeves",45,14,"arms",1,0,"noble"],["nobleSleeves3","Emerald noble sleeves",45,14,"arms",1,0,"noble"],["nobleTrousers1","Crimson noble trousers",60,18,"legs",2,0,"noble"],["nobleTrousers2","Royal blue noble trousers",60,18,"legs",2,0,"noble"],["nobleTrousers3","Emerald noble trousers",60,18,"legs",2,0,"noble"],["nobleBoots1","Crimson noble boots",45,14,"boots",1,0,"noble"],["nobleBoots2","Royal blue noble boots",45,14,"boots",1,0,"noble"],["nobleBoots3","Emerald noble boots",45,14,"boots",1,0,"noble"],["peasantShirt1","Brown shirt",8,2,"chest",0,0,"peasant"],["peasantShirt2","Charcoal shirt",8,2,"chest",0,0,"peasant"],["peasantShirt3","Blue shirt",8,2,"chest",0,0,"peasant"],["peasantSleeves1","Brown sleeves",5,2,"arms",0,0,"peasant"],["peasantSleeves2","Charcoal sleeves",5,2,"arms",0,0,"peasant"],["peasantSleeves3","Blue sleeves",5,2,"arms",0,0,"peasant"],["peasantTrousers1","Brown trousers",8,2,"legs",0,0,"peasant"],["peasantTrousers2","Charcoal trousers",8,2,"legs",0,0,"peasant"],["peasantTrousers3","Blue trousers",8,2,"legs",0,0,"peasant"],["peasantShoes1","Brown shoes",6,2,"boots",0,0,"peasant"],["peasantShoes2","Charcoal shoes",6,2,"boots",0,0,"peasant"],["peasantShoes3","Blue shoes",6,2,"boots",0,0,"peasant"],["rangerHood1","Forest ranger hood",35,11,"helm",2,0,"ranger"],["rangerHood2","Shadow ranger hood",40,12,"helm",2,0,"ranger"],["rangerHood3","Hunter ranger hood",35,11,"helm",2,0,"ranger"],["rangerPauldron1","Forest ranger pauldron",25,8,"shoulders",1,0,"ranger"],["rangerPauldron2","Shadow ranger pauldron",29,9,"shoulders",1,0,"ranger"],["rangerPauldron3","Hunter ranger pauldron",25,8,"shoulders",1,0,"ranger"],["rangerTunic1","Forest ranger tunic",45,14,"chest",5,1,"ranger"],["rangerTunic2","Shadow ranger tunic",52,16,"chest",6,1,"ranger"],["rangerTunic3","Hunter ranger tunic",45,14,"chest",5,1,"ranger"],["rangerBracers1","Forest ranger bracers",30,9,"arms",2,0,"ranger"],["rangerBracers2","Shadow ranger bracers",35,10,"arms",2,0,"ranger"],["rangerBracers3","Hunter ranger bracers",30,9,"arms",2,0,"ranger"],["rangerTrousers1","Forest ranger trousers",35,11,"legs",3,1,"ranger"],["rangerTrousers2","Shadow ranger trousers",40,12,"legs",3,1,"ranger"],["rangerTrousers3","Hunter ranger trousers",35,11,"legs",3,1,"ranger"],["rangerBoots1","Forest ranger boots",30,9,"boots",2,0,"ranger"],["rangerBoots2","Shadow ranger boots",35,10,"boots",2,0,"ranger"],["rangerBoots3","Hunter ranger boots",30,9,"boots",2,0,"ranger"],["wizardRobeTop1","Blue wizard robe top",70,21,"chest",2,0,"wizard"],["wizardRobeTop2","Violet wizard robe top",70,21,"chest",2,0,"wizard"],["wizardRobeTop3","Crimson wizard robe top",70,21,"chest",2,0,"wizard"],["wizardBracers1","Blue wizard bracers",35,11,"arms",1,0,"wizard"],["wizardBracers2","Violet wizard bracers",35,11,"arms",1,0,"wizard"],["wizardBracers3","Crimson wizard bracers",35,11,"arms",1,0,"wizard"],["wizardRobeBottom1","Blue wizard robe bottom",60,18,"legs",1,0,"wizard"],["wizardRobeBottom2","Violet wizard robe bottom",60,18,"legs",1,0,"wizard"],["wizardRobeBottom3","Crimson wizard robe bottom",60,18,"legs",1,0,"wizard"],["wizardBoots1","Blue wizard boots",35,11,"boots",1,0,"wizard"],["wizardBoots2","Violet wizard boots",35,11,"boots",1,0,"wizard"],["wizardBoots3","Crimson wizard boots",35,11,"boots",1,0,"wizard"],["cape","Crimson cape",60,18,"cape",1,0,"","A crimson cape with gold clasps."]]'::jsonb) r),
 labels as (select '{"helm":"Head","shoulders":"Shoulders","neck":"Neck","chest":"Body","arms":"Arms","legs":"Legs","boots":"Feet","cape":"Back"}'::jsonb l)
insert into eldervale_private.realm_catalog(id,data)
select 'item:armor:'||k,jsonb_build_object('name',case when k='cape' then 'Crimson cape' else name end,'buy',buy,'sell',sell,'field','armorOwned','key',k,'slot',slot) from spec
union all
select 'armor:'||k,jsonb_build_object('name',case when k='cape' then 'Crimson Adventurer Cape' else name end,'desc',coalesce(descr,initcap(outfit)||' outfit · '||lower(name)||'.'),'slot',l->>slot,'defence',defence,'reduction',reduction) from spec,labels
on conflict (id) do update set data=excluded.data;

do $migration$
declare
 def text;
 old_branch constant text := 'if field=''armorOwned'' then if slot<>key then raise exception ''Wrong equipment slot'';end if;s.equipment:=s.equipment||jsonb_build_object(key,not coalesce((s.equipment->>key)::boolean,false));';
 new_branch constant text := 'if field=''armorOwned'' then if coalesce(c->>''slot'',key)<>slot then raise exception ''Wrong equipment slot'';end if;if not coalesce((s.equipment->>key)::boolean,false) then s.equipment:=s.equipment||coalesce((select jsonb_object_agg(e.k,false) from jsonb_each_text(s.equipment) e(k,v) join eldervale_private.realm_catalog r on r.id=''item:armor:''||e.k where e.v=''true'' and e.k<>key and coalesce(r.data->>''slot'',e.k)=slot),''{}''::jsonb);end if;s.equipment:=s.equipment||jsonb_build_object(key,not coalesce((s.equipment->>key)::boolean,false));';
begin
 select pg_get_functiondef(p.oid) into def from pg_proc p join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='eldervale_private' and p.proname='realm_request_base';
 if md5(def)<>'9ad5c5971cee14acb225a85f1f33e5b4' then raise exception 'realm_request_base changed since this migration was reviewed'; end if;
 if (length(def)-length(replace(def,old_branch,'')))/length(old_branch)<>1 then raise exception 'equip armour branch not found exactly once'; end if;
 execute replace(def,old_branch,new_branch);
end
$migration$;

commit;
